118	std::vector<size_t> getRelevantSubstructTermIndices(
119	    const ROMol &mol, const std::vector<SubstructTerm> &terms) {
120	  // Prepare relevant SubstructTerms for this molecule by filtering in two
121	  // stages:
122	  //   1. Element check: skip terms requiring elements not in the molecule
123	  //   2. Connectivity check: skip terms whose bond-order-agnostic pattern
124	  //      doesn't match (since tautomerization doesn't create/destroy bonds)
125	
126	  std::unordered_set<int> presentElements;
127	  for (const auto atom : mol.atoms()) {
128	    presentElements.insert(atom->getAtomicNum());
129	  }
130	
131	  std::vector<size_t> relevantIndices;
132	  relevantIndices.reserve(terms.size());
133	
134	  SubstructMatchParameters params;
135	  params.maxMatches = 1;
136	
137	  for (size_t i = 0; i < terms.size(); ++i) {
138	    const auto &term = terms[i];
139	
140	    bool hasAllElements = true;
141	    for (int elem : term.requiredElements) {
142	      if (presentElements.find(elem) == presentElements.end()) {
143	        hasAllElements = false;
144	        break;
145	      }
146	    }
147	    if (!hasAllElements) {
148	      continue;
149	    }
150	    if (term.connectivityMatcher.getNumAtoms() > 0) {
151	      auto matches = SubstructMatch(mol, term.connectivityMatcher, params);
152	      if (matches.empty()) {
153	        continue;
154	      }
155	    }
156	    relevantIndices.push_back(i);
157	  }
158	
159	  return relevantIndices;
160	}
