169	// Count bonds between two element types with double or aromatic bond order.
170	// Matches: [#elem1]=,:[#elem2]
171	inline unsigned int countDoubleOrAromaticBonds(const ROMol &mol, int elem1,
172	                                               int elem2) {
173	  unsigned int count = 0;
174	  for (const auto bond : mol.bonds()) {
175	    const auto bt = bond->getBondType();
176	    if (bt != Bond::DOUBLE && bt != Bond::AROMATIC) {
177	      continue;
178	    }
179	    const int a1 = bond->getBeginAtom()->getAtomicNum();
180	    const int a2 = bond->getEndAtom()->getAtomicNum();
181	    if ((a1 == elem1 && a2 == elem2) || (a1 == elem2 && a2 == elem1)) {
182	      ++count;
183	    }
184	  }
185	  return count;
186	}
