192	    if (atom->getAtomicNum() != 6) {
193	      continue;
194	    }
195	    // X4 means total degree 4 (including implicit H)
196	    if (atom->getTotalDegree() != 4) {
197	      continue;
198	    }
199	    // H3 means exactly 3 total hydrogens
200	    if (atom->getTotalNumHs() != 3) {

    if (atom->getTotalNumHs() != 3) {
      continue;
    }
    ++count;
  }
  return count;
