                  nbrBndJ->getStereo() != Bond::STEREOANY &&
                  nbrBndJ->getStereo() != Bond::STEREONONE) {
                okToClear = false;
                break;
              }
            }
            if (okToClear) {
              nbrBndI->setBondDir(Bond::NONE);
