using namespace RDKit;

static std::string readFile(const std::string &p) {
  std::ifstream in(p);
  std::ostringstream b;
  b << in.rdbuf();
  return b.str();
}

int main(int argc, char **argv) {
  std::string dir = argv[1];
  std::vector<std::string> files;
  for (const auto &e : std::filesystem::directory_iterator(dir)) {
    auto p = e.path().string();
    if (p.size() > 4 && p.substr(p.size() - 4) == ".sdf" &&
        std::filesystem::exists(p + ".expected.cxsmi")) {
      files.push_back(p);
    }
  }
  std::sort(files.begin(), files.end());
  int pass = 0, fail = 0, err = 0;
  for (const auto &f : files) {
    std::string expected = readFile(f + ".expected.cxsmi");
    try {
      std::unique_ptr<RWMol> mol(MolBlockToMol(readFile(f), false, false, false));
      if (!mol) { std::cout << "PARSEFAIL " << f << "\n"; ++err; continue; }
      RDKit::Chirality::removeNonExplicit3DChirality(*mol);
      SmilesWriteParams ps;
      ps.canonical = false;
      ps.doKekule = true;
      unsigned int flags = SmilesWrite::CXSmilesFields::CX_COORDS |
                           SmilesWrite::CXSmilesFields::CX_MOLFILE_VALUES |
                           SmilesWrite::CXSmilesFields::CX_ATOM_PROPS |
                           SmilesWrite::CXSmilesFields::CX_BOND_CFG |
                           SmilesWrite::CXSmilesFields::CX_ENHANCEDSTEREO;
      auto out = MolToCXSmiles(*mol, ps, flags, RestoreBondDirOptionTrue);
      if (out == expected) {
        ++pass;
      } else {
        ++fail;
        std::cout << "MISMATCH " << std::filesystem::path(f).filename().string() << "\n  got: " << out
                  << "\n  exp: " << expected << "\n";
      }
    } catch (const std::exception &e) {
      ++err;
      std::cout << "EXC " << std::filesystem::path(f).filename().string() << ": " << e.what() << "\n";
    }
  }
  std::cout << "pass=" << pass << " fail=" << fail << " err=" << err << "\n";
  return 0;
