static std::string describe(const ROMol &m) {
  std::ostringstream os;
  os << MolToSmiles(m) << " |";
  for (const auto b : m.bonds()) {
    if (b->getStereo() != Bond::STEREONONE || !b->getStereoAtoms().empty()) {
      os << " b" << b->getIdx() << ":t" << b->getBondType() << ":s"
         << b->getStereo() << ":n" << b->getStereoAtoms().size();
    }
  }
  for (const auto a : m.atoms()) {
    if (a->getChiralTag() != Atom::CHI_UNSPECIFIED) {
      os << " a" << a->getIdx() << ":c" << a->getChiralTag();
    }
  }
  return os.str();
}

static void report(const std::string &label, const ROMol &mol) {
  for (int rbs = 0; rbs < 2; ++rbs) {
    MolStandardize::TautomerEnumerator te;
    te.setRemoveBondStereo(rbs == 1);
    std::cout << label << " rbs=" << rbs;
    try {
      std::unique_ptr<ROMol> can(te.canonicalize(mol));
      std::cout << " canon=[" << describe(*can) << "]";
      // coherence checks
      for (const auto b : can->bonds()) {
        if (b->getStereo() > Bond::STEREOANY) {
          bool atrop = b->getStereo() == Bond::STEREOATROPCW ||
                       b->getStereo() == Bond::STEREOATROPCCW;
          if (atrop) {
            if (b->getBondType() != Bond::SINGLE) {
              std::cout << " INCOHERENT(atrop-on-nonsingle b" << b->getIdx() << ")";
            }
          } else if (b->getBondType() != Bond::DOUBLE ||
                     b->getStereoAtoms().size() != 2) {
            std::cout << " INCOHERENT(b" << b->getIdx() << ")";
          }
        }
      }
      std::string pkl;
      MolPickler::pickleMol(*can, pkl, PicklerOps::AllProps);
      ROMol rt;
      MolPickler::molFromPickle(pkl, rt);
      if (MolToSmiles(rt) != MolToSmiles(*can)) {
        std::cout << " PICKLE_MISMATCH";
      }
    } catch (const std::exception &e) {
      std::cout << " canon=FAILED(" << e.what() << ")";
    }
    try {
      MolStandardize::TautomerEnumerator te2;
      te2.setRemoveBondStereo(rbs == 1);
      auto res = te2.enumerate(mol);
      std::cout << " n=" << res.size();
      std::vector<std::string> smis = res.smiles();
      std::sort(smis.begin(), smis.end());
      std::cout << " tauts=[";
      for (size_t i = 0; i < smis.size(); ++i) {
        if (i) std::cout << ",";
        std::cout << smis[i];
      }
      std::cout << "]";
    } catch (const std::exception &e) {
      std::cout << " enum=FAILED(" << e.what() << ")";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  // arg1: file with one input per line: either SMILES or path to molfile
  std::ifstream list(argv[1]);
  std::string line;
  while (std::getline(list, line)) {
    if (line.empty() || line[0] == '#') continue;
    std::unique_ptr<ROMol> mol;
    std::string label = line;
    try {
      if (std::filesystem::exists(line)) {
        label = std::filesystem::path(line).filename().string();
        auto txt = readFile(line);
        mol.reset(MolBlockToMol(txt));
      } else {
        mol.reset(SmilesToMol(line));
      }
    } catch (const std::exception &e) {
      std::cout << label << " LOAD_EXC " << e.what() << std::endl;
      continue;
    }
    if (!mol) {
      std::cout << label << " LOAD_FAILED" << std::endl;
      continue;
    }
    report(label, *mol);
  }
  return 0;
}

