#include <GraphMol/FileParsers/FileParsers.h>
#include <GraphMol/MolStandardize/Tautomer.h>
#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesParse.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>
#include <GraphMol/MolPickler.h>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <sstream>

using namespace RDKit;

static std::string readFile(const std::string &p) {
  std::ifstream in(p);
  std::ostringstream b;
  b << in.rdbuf();
  return b.str();
}

static std::string coherence(const ROMol &m) {
  std::ostringstream os;
  for (const auto b : m.bonds()) {
    const auto s = b->getStereo();
    if (s == Bond::STEREOATROPCW || s == Bond::STEREOATROPCCW) {
      if (b->getBondType() != Bond::SINGLE) {
        os << " ATROP_ON_NONSINGLE(b" << b->getIdx() << ")";
      }
    } else if (s > Bond::STEREOANY) {
      if (b->getBondType() != Bond::DOUBLE) {
        os << " EZ_ON_NONDOUBLE(b" << b->getIdx() << ")";
      }
      if (b->getStereoAtoms().size() != 2) {
        os << " EZ_WITHOUT_STEREOATOMS(b" << b->getIdx() << ")";
      }
    }
  }
  return os.str();
}

static void checkSerialization(const std::string &label, const ROMol &m) {
  std::string issues = coherence(m);
  try {
    auto smi = MolToSmiles(m);
    if (smi.empty()) issues += " EMPTY_SMILES";
    std::unique_ptr<ROMol> rp{SmilesToMol(smi)};
    if (!rp) issues += " SMILES_NOT_PARSEABLE";
    else if (MolToSmiles(*rp) != smi) issues += " SMILES_NOT_ROUNDTRIP";
  } catch (const std::exception &e) {
    issues += std::string(" SMILES_EXC(") + e.what() + ")";
  }
  try {
    auto cx = MolToCXSmiles(m);
    if (cx.empty()) issues += " EMPTY_CXSMILES";
  } catch (const std::exception &e) {
    issues += std::string(" CXSMILES_EXC(") + e.what() + ")";
  }
  try {
    auto mb = MolToMolBlock(m);
    std::unique_ptr<ROMol> rp{MolBlockToMol(mb)};
    if (!rp) issues += " V2000_NOT_PARSEABLE";
  } catch (const std::exception &e) {
    issues += std::string(" V2000_EXC(") + e.what() + ")";
  }
  try {
    auto mb = MolToV3KMolBlock(m);
    std::unique_ptr<ROMol> rp{MolBlockToMol(mb)};
    if (!rp) issues += " V3000_NOT_PARSEABLE";
  } catch (const std::exception &e) {
    issues += std::string(" V3000_EXC(") + e.what() + ")";
  }
  try {
    std::string pkl;
    MolPickler::pickleMol(m, pkl, PicklerOps::AllProps);
    ROMol rt;
    MolPickler::molFromPickle(pkl, rt);
    if (MolToSmiles(rt) != MolToSmiles(m)) issues += " PICKLE_MISMATCH";
    issues += coherence(rt);
  } catch (const std::exception &e) {
    issues += std::string(" PICKLE_EXC(") + e.what() + ")";
  }
  if (!issues.empty()) {
    std::cout << label << issues << std::endl;
  }
}

int main(int argc, char **argv) {
  std::ifstream list(argv[1]);
  std::string line;
  size_t n = 0;
  while (std::getline(list, line)) {
    if (line.empty() || line[0] == '#') continue;
    std::unique_ptr<RWMol> mol;
    std::string label = line;
    try {
      if (std::filesystem::exists(line)) {
        label = std::filesystem::path(line).filename().string();
        mol.reset(MolBlockToMol(readFile(line)));
      } else {
        mol.reset(SmilesToMol(line));
      }
    } catch (const std::exception &) {
      continue;
    }
    if (!mol) continue;
    ++n;
    for (int rbs = 0; rbs < 2; ++rbs) {
      for (int sp3 = 0; sp3 < 2; ++sp3) {
        MolStandardize::TautomerEnumerator te;
        te.setRemoveBondStereo(rbs == 1);
        te.setRemoveSp3Stereo(sp3 == 1);
        std::string tag = label + " rbs=" + std::to_string(rbs) + " sp3=" +
                          std::to_string(sp3);
        try {
          std::unique_ptr<ROMol> can{te.canonicalize(*mol)};
          checkSerialization(tag + " canonicalize", *can);
        } catch (const std::exception &e) {
          std::cout << tag << " canonicalize EXC(" << e.what() << ")"
                    << std::endl;
        }
        try {
          RWMol cp(*mol);
          te.canonicalizeInPlace(cp);
          checkSerialization(tag + " canonicalizeInPlace", cp);
        } catch (const std::exception &e) {
          std::cout << tag << " canonicalizeInPlace EXC(" << e.what() << ")"
                    << std::endl;
        }
        try {
          auto res = te.enumerate(*mol);
          for (const auto &t : res) {
            checkSerialization(tag + " taut", *t);
          }
        } catch (const std::exception &e) {
          std::cout << tag << " enumerate EXC(" << e.what() << ")" << std::endl;
        }
      }
    }
  }
  std::cout << "checked " << n << " inputs" << std::endl;
  return 0;
}
